  "root_cause": "The adjustDate method adds/subtracts milliseconds (24*60*60*1000) to shift dates, which does not account for daylight‑saving time changes. When crossing a DST fallback (as in Europe/London on 2026‑10‑25), the millisecond shift results in a date that is one day earlier than expected, causing ArrowDown to move the date by six days instead of seven.",
  "repair_strategy": "Replace the millisecond‑based date arithmetic in adjustDate with calendar‑date manipulation using Date.setDate. This adds/subtracts days directly, preserving the time‑of‑day (midnight) and automatically handling month/year rollovers without DST‑related offsets.",
  "edits": [
    {
      "path": "pikaday.js",
      "sha256": "86adae7e6b934af216fc65b90e3e8b99c90263dd035acd47cc2b717640cd4b9a",
      "before": "        adjustDate: function(sign, days) {

            var day = this.getDate() || new Date();
            var difference = parseInt(days)*24*60*60*1000;

            var newDay;

            if (sign === 'add') {
                newDay = new Date(day.valueOf() + difference);
            } else if (sign === 'subtract') {
                newDay = new Date(day.valueOf() - difference);
            }

            // skip disabled days
            var opts = this._o;
            var maxIter = 366;
            var found = false;
            while (maxIter--) {
                if (opts.minDate && newDay < opts.minDate) {
                    break;
                }
                if (opts.maxDate && newDay > opts.maxDate) {
                    break;
                }
                var disabled = false;
                if (opts.disableWeekends) {
                    var w = newDay.getDay();
                    if (w === 0 || w === 6) disabled = true;
                }
                if (opts.disableDayFn && opts.disableDayFn(newDay)) {
                    disabled = true;
                }
                if (!disabled) {
                    found = true;
                    break;
                }
                // move one more day in the same direction
                if (sign === 'add') {
                    newDay = new Date(newDay.valueOf() + 24*60*60*1000);
                } else {
                    newDay = new Date(newDay.valueOf() - 24*60*60*1000);
                }
            }
            if (!found) {
                newDay = day;
            }

            this.setDate(newDay);
        },",
      "after": "        adjustDate: function(sign, days) {
            var day = this.getDate() || new Date();
            var newDay = new Date(day.getTime());
            if (sign === 'add') {
                newDay.setDate(newDay.getDate() + days);
            } else if (sign === 'subtract') {
                newDay.setDate(newDay.getDate() - days);
            }
            // skip disabled days
            var opts = this._o;
            var maxIter = 366;
            var found = false;
            while (maxIter--) {
                if (opts.minDate && newDay < opts.minDate) {
                    break;
                }
                if (opts.maxDate && newDay > opts.maxDate) {
                    break;
                }
                var disabled = false;
                if (opts.disableWeekends) {
                    var w = newDay.getDay();
                    if (w === 0 || w === 6) disabled = true;
                }
                if (opts.disableDayFn && opts.disableDayFn(newDay)) {
                    disabled = true;
                }
                if (!disabled) {
                    found = true;
                    break;
                }
                // move one more day in the same direction
                if (sign === 'add') {
                    newDay.setDate(newDay.getDate() + 1);
                } else {
                    newDay.setDate(newDay.getDate() - 1);
                }
            }
            if (!found) {
                newDay = day;
            }
            this.setDate(newDay);
        },"
    }
  ],
  "expected_accessibility_effect": "ArrowDown will now correctly advance the date by one week (7 days) while skipping weekends, providing reliable keyboard navigation across DST transitions for users who rely on the arrow‑key date picker.",
  "functional_risks": [
    "Potential off‑by‑one errors when adding days to the last day of a month (setDate clamps to the last valid day, which matches the original millisecond behavior).",
    "The disableDayFn loop still increments/decrements by one day using setDate, preserving existing skipping logic.",
    "Minimum and maximum date checks remain unchanged and continue to work."
  ],
  "verification_requirements": [
    "Confirm that ArrowDown from a Friday date (e.g., 2026-10-23) yields the following Friday (2026-10-30) after the DST fallback.",
    "Confirm that ArrowUp correctly moves backward by one week across the same DST boundary.",
    "Verify navigation across month and year boundaries (e.g., from 2026-01-31 adding 7 days results in 2026-02-07).",
    "Ensure that minDate and maxDate constraints still prevent selection outside the allowed range.",
    "Ensure that weekend skipping (disableWeekends) and custom disableDayFn still work as intended."
  ]
}

